package com.example.profile;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;

interface MailSender {
    void send(String to);
}

@Configuration
public class ProfileBeans {

    @Bean
    @Profile("dev")
    public MailSender mockMailSender() {
        return to -> System.out.println("[MOCK] 发往 " + to);
    }

    @Bean
    @Profile("prod")
    public MailSender realMailSender() {
        return to -> System.out.println("[SMTP] 发往 " + to);
    }
}

// 业务代码面向 MailSender 接口注入，完全感知不到环境差异
// 注意：若 active=dev 时只有 mockMailSender 注册，注入 List 或单个均正常
